undef $/; $_=<STDIN>;
s/    if r < 0.5:\n/    if r < 0.3:\n        q = rng.randrange(1, P+1)\n        if q == pi or not content[q]: continue\n        k = rng.choice(content[q])\n        if k == i: continue\n        r2 = rng.randrange(0, P+1)\n        if r2 == q or (r2 == 0 and BK[k]): continue\n        if r2 == pi and pi != 0: continue\n        d = PEN[i][q] - PEN[i][pi] + PEN[k][r2] - PEN[k][q]\n        if d > 0 and rng.random() >= math.exp(-d\/T): continue\n        if not grp_ok(i, q, ignore=(k,)): continue\n        if G[k] is not None and r2 and G[k] == G[i] and spread(r2) == spread(pi): continue\n        if not grp_ok(k, r2, ignore=(i,)): continue\n        if G[k] is not None and r2 and G[k] == G[i] and spread(r2) == spread(q): continue\n        if not can_add(q, [i], [k]): continue\n        if r2 and not can_add(r2, [k], []): continue\n        unplace(i); unplace(k); place(i, q); place(k, r2)\n        cur += d\n    elif r < 0.6:\n/;
print;
